using System.Linq;
using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Dynamics;
internal sealed class FiniteCausalScheduleProtocolDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite causal schedules as executable quantum relation graphs",H("Finite causal schedules as executable quantum relation graphs"),
        Blocks(Describe.Lean(DescribeId.Create("program-graph-correspondence"),
            DeclarationHandle.Create("D5/S3/Quantum/Dynamics/FiniteCausalScheduleProtocol.program_graph_correspondence"),
            H("Finite adaptive programs have a unique normalized static relation solution"),StatementSource.FromAuthor(Disp(All("I",Call("Interface"),All("P",Call("Program",F.Id("I")),All("X",Call("CutState",F.Id("I")),Unique("phi",Call("Assignment",F.Id("P")),Conj(Call("GraphLaw",F.Id("phi")),Rel(Call("rootValue",F.Id("phi")),Eq,F.Id("X")),Rel(Call("SumTerminalTrace",Call("leaves",F.Id("phi"))),Eq,Call("Trace",F.Id("X")))))))))),AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/QuantumChannels/chiribella2009networks")),
            Blocks(Paragraph(Text("The program is a finite tree of actual normalized Kraus instruments. A child is selected by the observed outcome alone. Independently assigned prefix matrices satisfying only the local equations are uniquely reconstructed from the root, and terminal trace equals the root trace on every input matrix. Positive input gives positive terminal matrices by rectangular Kraus conjugation and finite positive sums."))),DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("causal-schedule-realization"),
            DeclarationHandle.Create("D5/S3/Quantum/Dynamics/FiniteCausalScheduleProtocol.causal_schedule_realization"),H("Finite causal schedules as executable quantum relation graphs"),
            StatementSource.FromAuthor(Disp(All("E",Call("Type"),Instance(Call("PartialOrder",F.Id("E")),All("G",Call("QuantumPortGraph",F.Id("E")),All("K",Call("Set",F.Id("E")),All("L",Call("Set",F.Id("E")),All("l",Call("List",F.Id("E")),All("h",Call("Records",Call("Outcomes",F.Id("G"))),All("X",Call("State",Call("Cut",F.Id("G"),F.Id("K"))),Rel(Conj(Call("Exec",F.Id("K"),F.Id("l"),F.Id("L")),Call("IsLowerSet",F.Id("K")),Call("IsLowerSet",F.Id("L")),Call("Finite",F.Id("L"))),Implies,Unique("phi",Call("Assignment",Call("compile",F.Id("G"),F.Id("l"),Call("RestrictRecord",F.Id("h"),F.Id("K")))),Conj(Call("GraphLaw",F.Id("phi")),Rel(Call("rootValue",F.Id("phi")),Eq,F.Id("X")),Rel(Call("SumTerminalTrace",Call("leaves",F.Id("phi"))),Eq,Call("Trace",F.Id("X"))),Call("Member",Call("RecordedTerminal",Call("ScheduledOutcomes",F.Id("l"),F.Id("h")),Call("Cut",F.Id("G"),F.Id("L")),Call("pathMap",Call("Readout",F.Id("G"),F.Id("h")),F.Id("l"),F.Id("X"))),Call("leaves",F.Id("phi"))),All("m",Call("List",F.Id("E")),Rel(Call("Exec",F.Id("K"),F.Id("m"),F.Id("L")),Implies,Rel(Call("pathMap",Call("Readout",F.Id("G"),F.Id("h")),F.Id("l"),F.Id("X")),Eq,Call("pathMap",Call("Readout",F.Id("G"),F.Id("h")),F.Id("m"),F.Id("X"))))),All("z",Call("Terminal"),Rel(Call("Member",F.Id("z"),Call("leaves",F.Id("phi"))),Implies,Rel(Call("HistoryLength",F.Id("z")),Eq,Call("Ncard",Call("Difference",F.Id("L"),F.Id("K"))))))))))))))))))),AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/QuantumChannels/chiribella2009networks")),
            Blocks(Paragraph(Text("The compiler reads a finite legal event schedule. At each step it constructs the actual normalized instrument from the graph Kraus data, branches on its finite observed outcome, extends only the observed record, and recursively compiles the remaining positive event occurrences. Hidden Kraus labels are summed and never control feedback. The resulting Program has concrete finite interfaces and a structurally finite termination bound equal to the schedule length. Every terminal record has this length, and the finite history clock theorem identifies it with the cardinality of the added event occurrences.")),
                Paragraph(Text("Independently assign matrices to all observed-prefix vertices of this executable tree. The graph law contains only neighboring CP equations. Recursion constructs a solution from any input boundary, and induction gives uniqueness. Terminal total trace equals input trace by the canonical CPTP supplier at each node. Early termination is admitted by the stop instruction. A fixed actual record selects an existing compiled terminal whose history is precisely the scheduled observed outcomes and whose full matrix is the original path composite.")),
                Paragraph(Text("For different legal topological schedules compare event-indexed records, rather than their differently ordered output strings. Derived disjoint-port interchange gives the same complete final matrix for every record and therefore the same joint probabilities and reference-boundary readouts. Conversely these local normalized instructions constitute a legal finite adaptive quantum protocol. FiniteInstrumentRelationGraph gives the corresponding construction directly for the canonical protocol Tree, including outcome-dependent dimensions, reference factors, independent ancillary densities, retained returning environments and early leaves.")),
                Paragraph(Text("A finite deterministic causal DAG can be executed in a topological order, as in Chiribella, D’Ariano and Perinotti, Theoretical framework for quantum networks (arXiv:0904.4483v2), Section II.C.1. Finite actual-outcome feedback unrolls it into a finite tree of real instruments; this is a fixed relation graph with a variable at every actual prefix. Finite Kraus representation is the existing quantum-foundation input for CP nodes, while unused external systems remain spectator coordinates and a returning environment remains an active port. All distributions are the prescribed instrument Born probabilities. Static representation does not derive the Born law, permit an infinite output interface, discard a returning environment, or erase positive occurrences."))),DescribeRole.Theorem))));
    private static Formula Call(string name, params Formula[] args) =>
        new Formula.FunctionCall(FormulaIdentifier.Create(name), [.. args]);

    private static Formula All(string name, Formula type, Formula body) =>
        Seq(Open, Forall, Sp, F.Id(name), Colon, Sp, type, Comma, Sp, body, Close);
    private static Formula Unique(string name, Formula type, Formula body) =>
        Seq(Open, Exists, Sp, Bang, Sp, F.Id(name), Colon, Sp, type, Comma, Sp, body, Close);
    private static Formula Rel(Formula left, Formula relation, Formula right) =>
        Seq(Open, left, Sp, relation, Sp, right, Close);
    private static Formula Conj(params Formula[] statements) =>
        statements.Aggregate((left, right) => Rel(left, Land, right));
    private static Formula Instance(Formula instance, Formula body) =>
        Seq(OpenBracket, instance, CloseBracket, Sp, body);
}
